import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/services/medical-data-collection/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Medical data collection","serviceType":"Research service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/medical-data-collection/","description":"Primary and secondary medical data collection for trials, registries and real-world studies. Bad data cannot be rescued by good analysis.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What types of medical data do you collect?","acceptedAnswer":{"@type":"Answer","text":"Clinical trial data, patient-reported outcomes, electronic health records, real-world evidence, epidemiological and registry data, adverse event and pharmacovigilance reports, and health economics data.\n\nPrimary collection and secondary extraction are usually combined — some variables have to be measured, others already exist in a record somewhere, and the cost difference between the two is large."}},{"@type":"Question","name":"How do you meet HIPAA, GDPR and local requirements?","acceptedAnswer":{"@type":"Answer","text":"Encryption, de-identification, secure transfer protocols and a documented consent process, applied as the design rather than as a final check.\n\nLocal data protection law is checked per jurisdiction, including data localisation mandates that restrict where records may physically be held. A multi-country study is built to the strictest standard involved rather than to the average of them."}},{"@type":"Question","name":"What collection methods do you use in clinical research?","acceptedAnswer":{"@type":"Answer","text":"Electronic data capture, paper CRFs, direct patient surveys, mobile health applications, wearable devices, patient registries and telehealth platforms.\n\nWhich of them is right is a protocol decision, not a preference. Wearable data is rich and cheap per record but carries adherence gaps; paper is reliable in low-connectivity settings and expensive to transcribe."}},{"@type":"Question","name":"How do you manage data quality and validation?","acceptedAnswer":{"@type":"Answer","text":"SOPs for validation, source data verification, real-time monitoring, audit trails and double-data entry where the study warrants it.\n\nThe part that matters most is the query cycle. Discrepancies are raised with the site and resolved at source, with the resolution logged — not corrected quietly, which is what an audit is looking for."}},{"@type":"Question","name":"Do you support observational and real-world studies?","acceptedAnswer":{"@type":"Answer","text":"Yes — observational studies, registries, real-world evidence generation and post-marketing surveillance, supporting outcomes research and health economics evaluation.\n\nThese are frequently harder than trials rather than easier, because the data was collected for care rather than for research and the confounding has to be handled at design."}},{"@type":"Question","name":"Can you handle multilingual data collection?","acceptedAnswer":{"@type":"Answer","text":"Yes. Instruments are translated and validated rather than translated only, with culturally adapted survey tools and localised patient engagement.\n\nFor validated scales this matters a great deal: a literal translation of a validated instrument is no longer the validated instrument, and reviewers ask."}},{"@type":"Question","name":"Do you do the statistical analysis as well?","acceptedAnswer":{"@type":"Answer","text":"Not as part of this service, but it is available as an extension of the same engagement.\n\nWhere analysis is ordered alongside collection, the statistician sees the data plan before collection starts — which is the arrangement that prevents the most expensive category of problem."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Research services","item":"https://pubrica.com/services/medical-data-collection/"}]}];

